CREATE TABLE "public"."CourseFundingOrganization" ("id" serial NOT NULL, "courseId" integer NOT NULL, "organizationId" integer NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id") , UNIQUE ("id"), UNIQUE ("courseId", "organizationId"));COMMENT ON TABLE "public"."CourseFundingOrganization" IS E'Junction table linking courses with their funding organizations'; 